   APIPermissionSet tab_api_permissions;
   tab_api_permissions.insert(APIPermission::kTab);
   URLPatternSet tab_hosts;
  tab_hosts.AddOrigin(UserScript::ValidUserScriptSchemes(),
                      url::Origin::Create(url).GetURL());
